// Content with portions generated by generative AI platform
package org.eclipse.kura.linux.watchdog;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.atomic.AtomicInteger;

import org.eclipse.kura.watchdog.CriticalComponent;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

public class CriticalComponentRegistrationSnapshotTest {

    private static final String REBOOT_CAUSE_FILE = "target/registrationSnapshotRebootCause";
    private static final int PING_INTERVAL_MS = 20;
    private static final int LONG_TIMEOUT_MS = 60000;
    private static final long REBOOT_WAIT_TIMEOUT_MS = 10000;
    private static final long OBSERVATION_TIME_MS = 300;

    private final SupervisionTestWatchdogServiceImpl svc = new SupervisionTestWatchdogServiceImpl();
    private final MutableCriticalComponent component = new MutableCriticalComponent();
    private RuntimeException registrationException;

    @Test
    public void timeoutChangedAfterRegistrationIsIgnored() throws Exception {
        givenComponentTimeout(LONG_TIMEOUT_MS);
        givenWatchdogServiceIsActivated();
        givenComponentIsRegistered();

        whenComponentTimeoutChangesTo(0);
        whenWatchdogIsObserved();

        thenNoRebootIsRequested();
    }

    @Test
    public void reRegistrationAppliesChangedTimeout() throws Exception {
        givenComponentName("reRegisteredComponent");
        givenComponentTimeout(LONG_TIMEOUT_MS);
        givenWatchdogServiceIsActivated();
        givenComponentIsRegistered();

        whenComponentTimeoutChangesTo(0);
        whenComponentIsRegisteredAgain();

        thenRebootIsRequested();
        thenRebootCauseIs("reRegisteredComponent");
    }

    @Test
    public void nameChangedAfterRegistrationIsNotUsedAsRebootCause() throws Exception {
        givenComponentName("nameAtRegistration");
        givenComponentTimeout(0);
        givenDisabledWatchdogServiceIsActivated();
        givenComponentIsRegistered();

        whenComponentNameChangesTo("nameAfterRegistration");
        whenWatchdogServiceIsEnabled();

        thenRebootIsRequested();
        thenRebootCauseIs("nameAtRegistration");
    }

    @Test
    public void watchdogThreadDoesNotCallComponentGetters() throws Exception {
        givenComponentTimeout(LONG_TIMEOUT_MS);
        givenWatchdogServiceIsActivated();
        givenComponentIsRegistered();

        whenWatchdogIsObserved();

        thenComponentTimeoutWasReadTimes(1);
        thenComponentNameWasReadTimes(1);
    }

    @Test
    public void registrationFailsWhenTimeoutGetterThrows() throws Exception {
        givenComponentTimeoutGetterThrows();
        givenWatchdogServiceIsActivated();

        whenComponentRegistrationIsAttempted();

        thenRegistrationFailedWithGetterException();
        thenNoComponentIsRegistered();
    }

    @Before
    public void deleteRebootCauseFileBefore() {
        new File(REBOOT_CAUSE_FILE).delete();
    }

    @After
    public void cleanup() {
        this.svc.deactivate();
        new File(REBOOT_CAUSE_FILE).delete();
    }

    private void givenComponentName(final String name) {
        this.component.name = name;
    }

    private void givenComponentTimeout(final int timeoutMs) {
        this.component.timeoutMs = timeoutMs;
    }

    private void givenComponentTimeoutGetterThrows() {
        this.component.timeoutGetterThrows = true;
    }

    private void givenWatchdogServiceIsActivated() {
        whenWatchdogServiceIsActivated();
    }

    private void givenDisabledWatchdogServiceIsActivated() {
        this.svc.activate(getProperties(false));
    }

    private void givenComponentIsRegistered() {
        this.svc.registerCriticalComponent(this.component);
    }

    private void whenWatchdogServiceIsActivated() {
        this.svc.activate(getProperties(true));
    }

    private void whenWatchdogServiceIsEnabled() {
        this.svc.updated(getProperties(true));
    }

    private void whenComponentTimeoutChangesTo(final int timeoutMs) {
        this.component.timeoutMs = timeoutMs;
    }

    private void whenComponentNameChangesTo(final String name) {
        this.component.name = name;
    }

    private void whenComponentIsRegisteredAgain() {
        this.svc.unregisterCriticalComponent(this.component);
        this.svc.registerCriticalComponent(this.component);
    }

    private void whenWatchdogIsObserved() throws InterruptedException {
        Thread.sleep(OBSERVATION_TIME_MS);
    }

    private void whenComponentRegistrationIsAttempted() {
        try {
            this.svc.registerCriticalComponent(this.component);
        } catch (RuntimeException e) {
            this.registrationException = e;
        }
    }

    private void thenNoRebootIsRequested() {
        assertEquals(0, this.svc.getRebootRequests());
    }

    private void thenRebootIsRequested() throws InterruptedException {
        assertTrue(this.svc.awaitRebootRequest(REBOOT_WAIT_TIMEOUT_MS));
    }

    private void thenRebootCauseIs(final String expectedCause) throws IOException {
        final List<String> lines = Files.readAllLines(new File(REBOOT_CAUSE_FILE).toPath());
        assertEquals(2, lines.size());
        assertEquals(expectedCause, lines.get(1));
    }

    private void thenComponentTimeoutWasReadTimes(final int expectedReads) {
        assertEquals(expectedReads, this.component.timeoutReads.get());
    }

    private void thenComponentNameWasReadTimes(final int expectedReads) {
        assertEquals(expectedReads, this.component.nameReads.get());
    }

    private void thenRegistrationFailedWithGetterException() {
        if (this.registrationException == null) {
            fail("Expected the registration to fail");
        }
        assertEquals(MutableCriticalComponent.GETTER_FAILURE, this.registrationException.getMessage());
    }

    private void thenNoComponentIsRegistered() {
        assertTrue(this.svc.getCriticalComponents().isEmpty());
    }

    private static Map<String, Object> getProperties(final boolean enabled) {
        final Map<String, Object> properties = new HashMap<>();
        properties.put("enabled", enabled);
        properties.put("watchdogMode", "fallback");
        properties.put("pingInterval", PING_INTERVAL_MS);
        properties.put("rebootCauseFilePath", REBOOT_CAUSE_FILE);
        return properties;
    }

    private static class MutableCriticalComponent implements CriticalComponent {

        static final String GETTER_FAILURE = "timeout getter failure";

        private final AtomicInteger nameReads = new AtomicInteger();
        private final AtomicInteger timeoutReads = new AtomicInteger();
        private volatile String name = "mutableComponent";
        private volatile int timeoutMs;
        private volatile boolean timeoutGetterThrows;

        @Override
        public String getCriticalComponentName() {
            this.nameReads.incrementAndGet();
            return this.name;
        }

        @Override
        public int getCriticalComponentTimeout() {
            this.timeoutReads.incrementAndGet();
            if (this.timeoutGetterThrows) {
                throw new IllegalStateException(GETTER_FAILURE);
            }
            return this.timeoutMs;
        }
    }
}
